GLuint Shader(GLenum k,std::string s){for(unsigned width:{3u,4u}){const std::string declaration=width==3?"vec3 corners[8][3]":"vec3 corners[6][4]";const auto begin=s.find(declaration);if(begin==s.npos)continue;const auto end=s.find("emitShapeVertex",begin);auto block=s.substr(begin,end-begin);block.replace(0,declaration.size(),"vec3 corners[24]");block=std::regex_replace(block,std::regex("corners\\[([^\\]]+)\\]\\[([^\\]]+)\\]"),"corners[($1)*"+std::to_string(width)+"+($2)]");s.replace(begin,end-begin,block);const auto call=s.find("corners[",begin+block.size());const auto tail=s.find(";",call);auto expression=s.substr(call,tail-call);expression=std::regex_replace(expression,std::regex("corners\\[([^\\]]+)\\]\\[([^\\]]+)\\]"),"corners[($1)*"+std::to_string(width)+"+($2)]");s.replace(call,tail-call,expression);}const auto at=s.find("#version 430 core");Check(at!=s.npos,"Original EEP GLSL version");s.replace(at,17,"#version 410 core");const std::string marker="//__ENGINEUNIFORMBUFFERDEFS__";const auto u=s.find(marker);Check(u!=s.npos,"Original EEP UBO interface marker");s.replace(u,marker.size(),"uniform mat4 cameraViewProj,cameraViewInv;uniform vec4 timeInfo;");auto o=glCreateShader(k);const char* raw=s.c_str();glShaderSource(o,1,&raw,nullptr);glCompileShader(o);GLint ok;glGetShaderiv(o,GL_COMPILE_STATUS,&ok);if(!ok){char log[8192]{};glGetShaderInfoLog(o,sizeof(log),nullptr,log);throw std::runtime_error(log);}return o;}
