 std::vector<uint8_t> Render(const NativeEnergyExplosionFrame& f,float z,unsigned path=0,bool capture=false){const bool literal=path!=0;const auto active=path==3?motionProgram:literal?literalProgram:program;CGLSetCurrentContext(context);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glViewport(0,0,W,H);glDisable(GL_SCISSOR_TEST);glDisable(GL_DITHER);glDisable(GL_CULL_FACE);glDisable(GL_MULTISAMPLE);glColorMask(true,true,true,true);glDepthMask(true);glClearColor(.02f,.03f,.04f,0);glClearDepth(z);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glEnable(GL_BLEND);glBlendFunc(GL_ONE,GL_ONE_MINUS_SRC_ALPHA);glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LEQUAL);glDepthMask(false);glUseProgram(active);glUniformMatrix4fv(glGetUniformLocation(active,"cameraViewProj"),1,false,f.cameraViewProjection.data());glUniformMatrix4fv(glGetUniformLocation(active,"cameraViewInv"),1,false,f.cameraViewInverse.data());glUniform4fv(glGetUniformLocation(active,"timeInfo"),1,f.timeInfo.data());
 GLuint feedback=0,query=0;if(capture){glGenBuffers(1,&feedback);glBindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,feedback);glBufferData(GL_TRANSFORM_FEEDBACK_BUFFER,68*42*25*4,nullptr,GL_STREAM_READ);glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER,0,feedback);glGenQueries(1,&query);glBeginQuery(GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN,query);if(path==3)glEnable(GL_RASTERIZER_DISCARD);glBeginTransformFeedback(path==3?GL_POINTS:GL_TRIANGLES);}for(const auto& d:f.draws){for(const auto&[name,v]:d.uniforms){auto p=glGetUniformLocation(active,name.c_str());if(name=="u_shape")glUniform1i(p,int(v[0]));else if(v.size()==3)glUniform3fv(p,1,v.data());else glUniform1f(p,v[0]);}glBindVertexArray(vao);glBindBuffer(GL_ARRAY_BUFFER,buffers[0]);const float triangle[12]={-1,-1,0,0,1,-1,1,0,-1,1,0,1};if(literal)glBufferData(GL_ARRAY_BUFFER,d.vertexSlots->bytes.size(),d.vertexSlots->bytes.data(),GL_STATIC_DRAW);else glBufferData(GL_ARRAY_BUFFER,sizeof(triangle),triangle,GL_STATIC_DRAW);glEnableVertexAttribArray(0);glVertexAttribPointer(0,literal?1:4,GL_FLOAT,false,literal?4:16,nullptr);glVertexAttribDivisor(0,0);glBindBuffer(GL_ARRAY_BUFFER,buffers[1]);glBufferData(GL_ARRAY_BUFFER,d.instances->bytes.size(),d.instances->bytes.data(),GL_STATIC_DRAW);for(unsigned n=1;n<=4;++n){glEnableVertexAttribArray(n);glVertexAttribPointer(n,4,GL_FLOAT,false,64,reinterpret_cast<const void*>((size_t(d.firstInstance)*64)+(n-1)*16));glVertexAttribDivisor(n,1);}glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,buffers[2]);const uint16_t tri[3]={0,1,2};const auto mapped=NativeEnergyExplosionGSIndices(d);glBufferData(GL_ELEMENT_ARRAY_BUFFER,literal?d.indices->bytes.size():sizeof(tri),literal?(path==2?static_cast<const void*>(mapped.data()):static_cast<const void*>(d.indices->bytes.data())):static_cast<const void*>(tri),GL_STATIC_DRAW);if(path==3)glDrawArraysInstanced(GL_POINTS,0,1,d.instanceCount);else glDrawElementsInstanced(GL_TRIANGLES,literal?d.indices->layout.elements:3,GL_UNSIGNED_SHORT,nullptr,d.instanceCount);}
 if(capture){glEndTransformFeedback();glEndQuery(GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN);GLuint count=0;glGetQueryObjectuiv(query,GL_QUERY_RESULT,&count);std::vector<float> values(count*(path==3?14:75));glBindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,feedback);glGetBufferSubData(GL_TRANSFORM_FEEDBACK_BUFFER,0,values.size()*4,values.data());std::ofstream out(output+(path==3?"/original-motion.f32":"/original-gs-vertices.f32"),std::ios::binary);out.write(reinterpret_cast<const char*>(values.data()),values.size()*4);glDeleteBuffers(1,&feedback);glDeleteQueries(1,&query);glDisable(GL_RASTERIZER_DISCARD);}std::vector<uint8_t> raw(W*H*4),top(raw.size());glReadPixels(0,0,W,H,GL_RGBA,GL_UNSIGNED_BYTE,raw.data());Check(glGetError()==GL_NO_ERROR,"Original EEP CGL error");for(unsigned y=0;y<H;++y)memcpy(top.data()+size_t(y)*W*4,raw.data()+size_t(H-1-y)*W*4,W*4);return top;}
