std::vector<uint8_t> Native(EnergyExplosionGPU& gpu,const NativeEnergyExplosionFrame& f,float z,bool omit){RuntimeLease lease;const auto start=Clock::now();auto d=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:W height:H mipmapped:NO];d.storageMode=MTLStorageModeShared;d.usage=MTLTextureUsageRenderTarget|MTLTextureUsageShaderRead;auto color=[lease.Device()newTextureWithDescriptor:d];Check(color!=nil,"Native EEP color");lease.AddAllocation(color);d=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatDepth32Float width:W height:H mipmapped:NO];d.storageMode=MTLStorageModePrivate;d.usage=MTLTextureUsageRenderTarget|MTLTextureUsageShaderRead;auto depth=[lease.Device()newTextureWithDescriptor:d];Check(depth!=nil,"Native EEP depth");lease.AddAllocation(depth);auto read=[lease.Device()newBufferWithLength:W*H*4 options:MTLResourceStorageModeShared];Check(read!=nil,"Native EEP depth readback");lease.AddAllocation(read);WorldCamera camera;camera.clipDepth=ClipDepthConvention::MinusOneToOne;double ms=0;auto p=omit?std::unique_ptr<PreparedEnergyExplosion>{}:gpu.Prepare(lease,f,camera,MTLPixelFormatRGBA8Unorm,MTLPixelFormatDepth32Float,true,ms);auto pass=[MTL4RenderPassDescriptor new];pass.renderTargetWidth=W;pass.renderTargetHeight=H;pass.colorAttachments[0].texture=color;pass.colorAttachments[0].loadAction=MTLLoadActionClear;pass.colorAttachments[0].storeAction=MTLStoreActionStore;pass.colorAttachments[0].clearColor=MTLClearColorMake(.02,.03,.04,0);pass.depthAttachment.texture=depth;pass.depthAttachment.loadAction=MTLLoadActionClear;pass.depthAttachment.storeAction=MTLStoreActionStore;pass.depthAttachment.clearDepth=z;lease.CommitResources();auto cmd=lease.Begin("Exact original EEP GLSL/Metal pixels");if(p)p->EncodeDependencies(cmd);auto e=[cmd renderCommandEncoderWithDescriptor:pass];Check(e!=nil,"Native EEP encoder");[e setViewport:MTLViewport{0,0,W,H,0,1}];[e setScissorRect:MTLScissorRect{0,0,W,H}];[e setCullMode:MTLCullModeBack];auto poisonDesc=[MTLDepthStencilDescriptor new];poisonDesc.depthCompareFunction=MTLCompareFunctionGreater;poisonDesc.depthWriteEnabled=YES;auto poison=[lease.Device()newDepthStencilStateWithDescriptor:poisonDesc];[e setDepthStencilState:poison];if(p)for(size_t n=0;n<p->DrawCount();++n){Check(p->SequenceAt(n)==f.draws[n].sequence,"Energy world sequence retained");p->EncodeDraw(n,e);}[e endEncoding];auto copy=[cmd computeCommandEncoder];Check(copy!=nil,"Native EEP depth copy");[copy barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageBlit visibilityOptions:MTL4VisibilityOptionDevice];[copy copyFromTexture:depth sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(W,H,1) toBuffer:read destinationOffset:0 destinationBytesPerRow:W*4 destinationBytesPerImage:0];[copy endEncoding];lease.SubmitAndWait(start,renders++);for(unsigned n=0;n<W*H;++n){float value;memcpy(&value,static_cast<const uint8_t*>(read.contents)+n*4,4);Check(value==z,"Original EEP must retain scene depth");}double readMs=0;return lease.Readback(color,W,H,readMs);}
}
int main(int argc,char** argv){@autoreleasepool{try{Check(argc>=3,"usage energy-gpu work result.json [omit|wrong-time]");work=argv[1];output=std::filesystem::path(argv[2]).parent_path().string();if(output.empty())output=".";std::filesystem::create_directories(output);const std::string fault=argc>3?argv[3]:"";auto baseline=Frame();GLReference gl;EnergyExplosionGPU gpu;Check(fault.empty()||fault=="omit"||fault=="wrong-time"||fault=="topology"||fault=="mapped-cgl","Unknown EEP oracle test mode");unsigned maximum=0,totalPaint=0,totalDifferent=0,topologyError=0,topologyDifferent=0;std::ostringstream cases;unsigned n=0;
 struct Scenario{std::string label;float time;unsigned shape;float depth;std::map<std::string,float> overrides;};std::vector<Scenario> scenarios;for(float time:{101.f,102.f,104.f,120.f,160.f,300.f})for(unsigned shape=0;shape<2;++shape)scenarios.push_back({"original-burst",time,shape,time==160?.2f:.95f,{}});for(unsigned shape=0;shape<2;++shape){scenarios.push_back({"faces-without-halo",104,shape,.95f,{{"glowIntensity",0}}});scenarios.push_back({"zero-radius-degenerate",104,shape,.95f,{{"drawRadius",0}}});scenarios.push_back({"fully-depth-occluded",104,shape,0,{}});scenarios.push_back({"GS-small-glow-threshold",104,shape,.95f,{{"glowIntensity",.0005f}}});}for(const auto& scenario:scenarios){const auto time=scenario.time;const auto shape=scenario.shape;auto f=baseline;f.timeInfo[0]=time;f.draws[0].uniforms["u_shape"]={float(shape)};f.draws[0].indices=Indices(shape);for(const auto&[name,value]:scenario.overrides)f.draws[0].uniforms[name]={value};float z=scenario.depth;auto expected=gl.Render(f,z);auto literal=gl.Render(f,z,fault=="mapped-cgl"?2:1);for(size_t i=0;i<expected.size();++i){topologyError=std::max(topologyError,unsigned(std::abs(int(expected[i])-int(literal[i]))));topologyDifferent+=expected[i]!=literal[i];}if(fault=="topology"||fault=="mapped-cgl"){std::cerr<<"GS versus literal NoGS time "<<time<<" shape "<<shape<<" cumulative max "<<topologyError<<" different "<<topologyDifferent<<"\n";continue;}auto actualFrame=f;if(fault=="wrong-time")actualFrame.timeInfo[0]=time/30;auto actual=Native(gpu,actualFrame,z,fault=="omit");std::ofstream glBytes(output+"/pixels-gl-"+std::to_string(n)+".rgba",std::ios::binary);glBytes.write(reinterpret_cast<const char*>(expected.data()),expected.size());std::ofstream mtlBytes(output+"/pixels-metal-"+std::to_string(n)+".rgba",std::ios::binary);mtlBytes.write(reinterpret_cast<const char*>(actual.data()),actual.size());unsigned error=0,different=0,paint=0;for(size_t i=0;i<expected.size();++i){error=std::max(error,unsigned(std::abs(int(expected[i])-int(actual[i]))));different+=expected[i]!=actual[i];paint+=expected[i]!=(i%4==0?5:i%4==1?8:i%4==2?10:0);++checks;}maximum=std::max(maximum,error);totalPaint+=paint;totalDifferent+=different;if(n++)cases<<',';cases<<"{\"label\":\""<<scenario.label<<"\",\"time\":"<<time<<",\"shape\":"<<shape<<",\"maxError\":"<<error<<",\"differentChannels\":"<<different<<",\"paintedChannels\":"<<paint<<'}';std::cerr<<"time "<<time<<" shape "<<shape<<" max "<<error<<" different "<<different<<" painted "<<paint<<'\n';}
 if(fault=="topology"||fault=="mapped-cgl"){Check(fault=="mapped-cgl"||topologyDifferent>1000,"Original GS versus literal NoGS discrepancy must be visible");std::ofstream result(argv[2]);result<<"{\"status\":\"CONFIRMED_DIFFERENT\",\"maxChannelError\":"<<topologyError<<",\"differentChannels\":"<<topologyDifferent<<"}\n";return 0;}Check(totalPaint>1000,"Original EEP oracle requires visible nontrivial output");std::ofstream result(argv[2]);result<<"{\"status\":\""<<(maximum<=2?"PASS":"FAIL")<<"\",\"checks\":"<<checks<<",\"renders\":"<<renders<<",\"maxChannelError\":"<<maximum<<",\"differentChannels\":"<<totalDifferent<<",\"paintedChannels\":"<<totalPaint<<",\"cases\":["<<cases.str()<<"]}\n";result.close();Check(maximum<=2,"Exact original EEP GLSL/Metal pixels differ");std::cout<<"PASS "<<renders<<" original EEP CGL/Metal renders / "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}}
